+// ─── Rendering helpers ───────────────────────────────────────────────────────
+
+function screenshotText(response: Record<string, unknown>): string {
+	const lines = stringLines(response.lines);
+	const header =
+		`── viewport (window_top=${response.window_top}` +
+		`${response.alt_screen ? ", alt screen" : ""}` +
+		`${response.cursor ? `, cursor=${JSON.stringify(response.cursor)}` : ""}) ──`;
+	return `${header}\n${lines.map((line) => `│${line}`).join("\n")}`;
+}
+
+/**
+ * After-input screenshot: the renderer's viewport when a debug socket exists
+ * (and answers), else the emulator's screen.
+ */
+async function settled(
+	session: Session,
+	note: string,
+	waitMs = 180,
+): Promise<string> {
+	await sleep(waitMs);
+	if (session.sock) {
+		try {
+			const shot = await request(session, { op: "text" }, 3_000);
+			if (shot.ok !== false) return `${note}\n${screenshotText(shot)}`;
+		} catch {
+			// Renderer unavailable; fall back to the emulator.
+		}
+	}
+	return `${note}\n${session.screen.snapshot()}`;
+}
+
+/** Renders one `tree` response node (and its children) as outline rows. */
+function renderTree(node: unknown, depth: number, out: string[]) {
+	if (!node || typeof node !== "object") return;
+	const rect = field(node, "rect");
+	const id = field(node, "id");
+	const flags = [
+		field(node, "focused") === true ? "FOCUSED" : "",
+		field(node, "focusable") === true ? "focusable" : "",
+		field(node, "hidden") === true ? "hidden" : "",
+	]
+		.filter(Boolean)
+		.join(" ");
+	out.push(
+		"  ".repeat(depth) +
+			`${field(node, "kind")}${typeof id === "string" ? `#${id}` : ""}` +
+			(Array.isArray(rect)
+				? ` [${rect[0]},${rect[1]} ${rect[2]}x${rect[3]}]`
+				: "") +
+			(flags ? `  ${flags}` : ""),
+	);
+	const children = field(node, "children");
+	if (Array.isArray(children)) {
+		for (const child of children) renderTree(child, depth + 1, out);
+	}
+}
+
+const SEQUENCES: Record<string, string> = {
+	alt_enter: "\x1b[?1049h",
+	alt_leave: "\x1b[?1049l",
+	clear_scrollback: "\x1b[3J",
+	sync_begin: "\x1b[?2026h",
+	sync_end: "\x1b[?2026l",
+	mouse_on: "\x1b[?1003h",
+	mouse_off: "\x1b[?1003l",
+	cursor_hide: "\x1b[?25l",
+	cursor_show: "\x1b[?25h",
+};
+
+function count(haystack: Buffer, needle: string): number {
+	const bytes = Buffer.from(needle, "latin1");
+	let total = 0;
+	let from = 0;
+	for (;;) {
+		const index = haystack.indexOf(bytes, from);
+		if (index < 0) return total;
+		total += 1;
+		from = index + bytes.length;
+	}
+}
+
+/** Escapes control bytes so raw terminal output is printable. */
+function visible(bytes: Buffer): string {
+	let out = "";
+	for (const byte of bytes) {
+		if (byte === 0x1b) out += "\\e";
+		else if (byte === 0x0a) out += "\n";
+		else if (byte === 0x0d) out += "\\r";
+		else if (byte < 0x20 || byte === 0x7f)
+			out += `\\x${byte.toString(16).padStart(2, "0")}`;
+		else out += String.fromCharCode(byte);
+	}
+	return out;
+}
+
+/** Unescapes `\e`, `\r`, `\n`, `\t`, and `\xNN` in a `send` payload. */
+function unescapeBytes(text: string): Buffer {
+	const out: number[] = [];
+	for (let index = 0; index < text.length; index++) {
+		if (text[index] !== "\\") {
+			out.push(...Buffer.from(text[index], "utf8"));
+			continue;
+		}
+		const next = text[index + 1];
+		if (next === "e") {
+			out.push(0x1b);
+			index++;
+		} else if (next === "r") {
+			out.push(0x0d);
+			index++;
+		} else if (next === "n") {
+			out.push(0x0a);
+			index++;
+		} else if (next === "t") {
+			out.push(0x09);
+			index++;
+		} else if (next === "x") {
+			out.push(Number.parseInt(text.slice(index + 2, index + 4), 16));
+			index += 3;
+		} else {
+			out.push(0x5c);
+		}
+	}
+	return Buffer.from(out);
+}
+
+/**
+ * Wraps `command` so the PTY child blocks until `gate` exists, then execs the
+ * real command in place (same pid, still the session leader).
+ *
+ * Bun (1.4.2, macOS) arms its exit watch inside `Bun.spawn`; a child already
+ * exiting by then makes it fall back to a blocking `wait4` on the JS thread. A
+ * PTY session leader cannot finish exiting until its unread output drains, and
+ * the only reader is that same blocked thread — so a fast command (`git grep`)
+ * deadlocked the whole agent. Creating `gate` only after `Bun.spawn` returns
+ * guarantees the watch is armed before the child can exit.
+ */
+function gated(gate: string, command: string[]): string[] {
+	const script = 'gate=$1; shift; while [ ! -e "$gate" ]; do sleep 0.01; done; exec "$@"';
+	return ["/bin/sh", "-c", script, "sh", gate, ...command];
+}
+/**
+ * Launch an executable directly on ConPTY. Race PID delivery against process
+ * completion so a failed spawn cannot leave start waiting for a missing callback.
+ */
+async function startWindowsPty(
+	options: PtyArgvStartOptions,
+	onData: (chunk: Uint8Array) => void,
+): Promise<Child> {
+	const pty = new PtySession();
+	const inputDecoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
+	const started = Promise.withResolvers<number>();
+	let running = true;
+	const exited = pty
+		.startArgv(
+			options,
+			(error, chunk) => {
+				if (error) started.reject(error);
+				else onData(Buffer.from(chunk));
+			},
+			(error, pid) => {
+				if (error) started.reject(error);
+				else started.resolve(pid);
+			},
+		)
+		.then((result) => result.exitCode ?? (result.cancelled ? -9 : 1))
+		.finally(() => {
+			running = false;
+		});
+	// `close` repeats `kill` during teardown; signal the native session once.
+	const kill = () => {
+		if (!running) return;
+		running = false;
+		pty.kill();
+	};
+	try {
+		const pid = await Promise.race([
+			started.promise,
+			exited.then((code) => {
+				throw new Error(`PTY exited before reporting its pid (code ${code})`);
+			}),
+		]);
+		return {
+			pid,
+			exited,
+			kill,
+			terminal: {
+				write(data) {
+					let text: string;
+					if (typeof data === "string") {
+						text = data;
+					} else {
+						try {
+							text = inputDecoder.decode(data);
+						} catch (error) {
+							throw new Error(
+								"Windows PTY input must be valid UTF-8; raw non-UTF-8 bytes are not supported",
+								{ cause: error },
+							);
+						}
+					}
+					pty.write(text);
+				},
+				resize(cols, rows) {
+					pty.resize(cols, rows);
+				},
+				close: kill,
+			},
+		};
+	} catch (error) {
+		kill();
+		await exited.catch(() => {});
+		throw error;
+	}
+}
