+				"edit {new:?}"
+			);
+			if new.starts_with("function a() {\n  return 2;") {
+				assert_eq!(
+					subtree_id(&tree, 1),
+					reused,
+					"the untouched function is reused, not reparsed"
+				);
+			}
+		}
