+					// remainder is empty) is this option's value.
+					if cluster[index + ch.len_utf8()..].is_empty() {
+						skip_value = true;
+					}
+					break;
+				}
+			}
+			if !rewrote {
+				out.push(arg);
+			}
+		} else {
+			out.push(arg);
+		}
+	}
